// ---- Etapas del pipeline (Inbound es aparte: son reglas, no negocios) ----
const STAGES = [
  { id: "prospeccion", name: "Prospección", dot: "#9CA3AF" },
  { id: "oferta", name: "Oferta y Negociación", dot: "#703EFF" }, // morado: el ámbar/naranja se leía como pérdida
  { id: "aceptadas", name: "Aceptada", dot: C.green },
  { id: "cesion", name: "Cesión", dot: C.green },
  { id: "otorgamiento", name: "Otorgamiento", dot: "#7c3aed" },
  { id: "giro", name: "Giro", dot: C.green },
  { id: "perdida", name: "Perdida", dot: C.red },
];
const STAGE_ORDER = STAGES.map((s) => s.id);
const stageById = (id) => STAGES.find((s) => s.id === id);
const stageName = (id) => (stageById(id) || {}).name || id; // a nivel de módulo: la usan DealCard (tarjetas perdidas) y TablaOportunidades
// ── Eje de NEGOCIO de una operación (además del `stage` = motor de estados): status + result + disbursement.
// El motor `stage` se conserva como atributo; el tablero se filtra por status = open.
//  · status:       open | closed
//  · result:       (sólo si closed) won | lost | expired   — expired (caducada por inacción) se separa de lost.
//  · disbursement: (operación aceptada) pending | disbursed — "Giro" deja de ser etapa: es sub-estado de Aceptada.
function dealDisbursement(d) {
  if (!d) return null;
  if (d.stage === "giro") return d.giroPendiente ? "pending" : "disbursed";
  if (d.stage === "aceptadas" || d.stage === "cesion") return "pending";
  return null;
}
function dealResult(d) {
  if (!d) return null;
  if (dealDisbursement(d) === "disbursed") return "won"; // girada = desembolsada = ganada
  if (d.stage === "perdida") {
    const c = String((typeof causaPerdidaDeal === "function" ? causaPerdidaDeal(d) : (d.causaPerdida || d.status || ""))).toLowerCase();
    if (d.expired || /sin contacto|inactiv|caduc|expir|no respond|intentos.*agotad/.test(c)) return "expired";
    return "lost";
  }
  return null;
}
const dealStatus = (d) => (dealResult(d) ? "closed" : "open");
// Etapa a MOSTRAR en tablero/tabla: "giro" ya no es etapa visible → se muestra como "Aceptada".
const displayStageId = (d) => (d && d.stage === "giro" ? "aceptadas" : (d && d.stage));
// Etiquetas para el usuario (español).
const STATUS_LBL = { open: "Abierta", closed: "Cerrada" };
const RESULT_LBL = { won: "Ganada", lost: "Perdida", expired: "Expirada" };
const RESULT_COL = { won: { bg: "#F0FDF4", fg: "#16A34A" }, lost: { bg: "#fef2f2", fg: "#DC2626" }, expired: { bg: "#FFF7ED", fg: "#C2410C" } };
const DISBURSEMENT_LBL = { pending: "Giro pendiente", disbursed: "Girada" };
const PAGE_SIZE = 8; // tarjetas por página en cada etapa (optimizado para 1800px)

// ---- Diálogo de confirmación destructiva (Datamart spec §26): nunca borrar a un clic ----
function ConfirmDialog({ abierto, titulo, descripcion, etiquetaConfirmar, onConfirmar, onCancelar }) {
  if (!abierto) return null;
  return (
    <div className="fixed inset-0 flex items-center justify-center ovl p-6" style={{ zIndex: 70 }} onClick={onCancelar}>
      <div onClick={(e) => e.stopPropagation()} className="w-full bg-white p-8 text-center" style={{ maxWidth: 480, borderRadius: 20, boxShadow: "0 20px 60px rgba(0,0,0,0.18)" }}>
        <div className="mx-auto mb-5 flex items-center justify-center rounded-full" style={{ width: 52, height: 52, border: "2px solid #DC2626" }}>
          <X size={24} style={{ color: "#DC2626" }} />
        </div>
        <div className="font-bold" style={{ fontSize: 22, color: C.ink }}>{titulo}</div>
        <div className="mt-2 t13" style={{ color: C.sub }}>{descripcion}</div>
        <div className="mt-6 flex justify-end gap-2">
          <button onClick={onCancelar} className="rounded-full px-6 py-2 t13 font-medium" style={{ border: `1.5px solid ${C.line}`, color: C.ink, backgroundColor: "#fff" }}>Volver</button>
          <button onClick={onConfirmar} className="rounded-full px-6 py-2 t13 font-semibold text-white" style={{ backgroundColor: "#EF4444" }}>{etiquetaConfirmar || "Eliminar"}</button>
        </div>
      </div>
    </div>
  );
}

// Sub-estados por etapa (con su icono-ojo como filtro on/off).
const UMBRAL_DEMORA_MS = 8000; // >3 horas de simulación sin avanzar -> "Demorado"
const SUBSTAGES = {
  prospeccion: [{ id: "contactado", name: "Contactado" }, { id: "errorcontacto", name: "Error contactabilidad" }, { id: "demorado", name: "Demorado (+3h)" }],
  oferta: [{ id: "enviada", name: "Oferta enviada" }, { id: "negociacion", name: "Negociación" }, { id: "firma", name: "Pendiente formalización" }],
  aceptadas: [{ id: "esperacesion", name: "Espera de cesión" }, { id: "enprocesocesion", name: "En proceso de cesión" }, { id: "cesionexterna", name: "Cesión externa" }],
  cesion: [{ id: "exitosa", name: "Exitosa" }, { id: "error", name: "Error" }],
  giro: [{ id: "girado", name: "Girado" }, { id: "pendiente", name: "Giro pendiente" }],
  otorgamiento: [{ id: "automatico", name: "Automático" }, { id: "porlinea", name: "Excede línea" }, { id: "porotros", name: "Otros deudores" }],
  perdida: [{ id: "perdido", name: "Perdido" }],
};
// Clasifica un negocio en un sub-estado según su etapa (estable por subSeed).
function subEstadoDe(d) {
  const s = d.subSeed != null ? d.subSeed : 0.5;
  switch (d.stage) {
    case "prospeccion":
      if (d.contactable === false && !d.telValidado && !d.emailValidado && !d.verifManual) return "errorcontacto";
      if (d.tProsp && (Date.now() - d.tProsp) > UMBRAL_DEMORA_MS) return "demorado";
      return "contactado";
    case "oferta": return s < 0.4 ? "enviada" : s < 0.8 ? "negociacion" : "firma";
    case "aceptadas": return d.cesionExterna ? "cesionexterna" : "esperacesion"; // ya firmada: espera/proceso de cesión (o cesión externa)
    case "cesion": return d.cesionExterna ? "cesionexterna" : "enprocesocesion"; // se muestra dentro de Aceptada
    case "giro": return d.giroPendiente ? "pendiente" : "girado"; // al llegar a Giro el anticipo ya se giró (cuenta como venta)
    case "otorgamiento": return d.otorgAuto ? "automatico" : d.otorgMotivo === "otros" ? "porotros" : "porlinea";
    case "perdida": return "perdido";
    default: return null;
  }
}

