// ---- Spread mínimo por deudor (buenos pagadores) ----
// Es el spread más bajo que el Agente IA está autorizado a ofrecer por cada deudor. La tasa final
// = spread + costo de fondo. Si el cliente pide una tasa que implica un spread por debajo de este
// mínimo, el bot no puede autorizarla y deriva la negociación a un ejecutivo.
const SPREAD_MIN_DEUDOR = {
  "Adidas Chile Limitada": 0.40, "Coca Cola Embonor S.A.": 0.35, "Clorox Chile S.A.": 0.42, "Sika S.A. Chile": 0.45,
  "Agrosuper Comercializadora": 0.40, "Laboratorio Durandin S.A.": 0.50, "Abbott Laboratories Chile": 0.45,
  "Comercial Mar Oceánica": 0.50, "Proquiel Químicos SpA": 0.52, "Constructora PyL SpA": 0.55,
  "SQM S.A.": 0.32, "Walmart Chile S.A.": 0.30, "Mantos Copper S.A.": 0.45, "Ministerio de Obras Públicas": 0.30,
  // Deudores de los eventos demo / streaming
  "Codelco": 0.30, "Escondida (BHP)": 0.32, "CMPC": 0.35, "Falabella": 0.40, "Cencosud": 0.40,
  "Arauco": 0.38, "Sodimac": 0.42, "Antofagasta Minerals": 0.34, "Walmart Chile": 0.30,
};
const SPREAD_MIN_DEFAULT = 0.60; // deudores no listados (mayor riesgo => piso más alto)
const spreadMinDeudor = (deudor) => SPREAD_MIN_DEUDOR[deudor] != null ? SPREAD_MIN_DEUDOR[deudor] : SPREAD_MIN_DEFAULT;
// Tasa mínima mensual que el Agente IA puede autorizar para un deudor (spread mínimo + costo de fondo).
const tasaMinIA = (deudor) => +(spreadMinDeudor(deudor) + COSTO_FONDO).toFixed(2);
// ── Precio por Share of Wallet ──────────────────────────────────────────────────────────────────
// El SOW define cuán agresivo se es en precio: se parte del spread ESTÁNDAR (de lista) y se descuentan
// puntos según el estado del SOW del cliente. El piso de riesgo del deudor SIEMPRE manda: si el
// descuento comercial perfora el spread mínimo del deudor, se trunca ahí.
const SPREAD_ESTANDAR = 0.60; // % mensual — spread de lista, sin descuento comercial
const SOW_AJUSTE = {
  target:      { pts: 0.00, l: "En target — tasa estándar" },
  creciendo:   { pts: 0.05, l: "Creciendo — descuento mínimo" },
  estable:     { pts: 0.10, l: "Estable bajo target — descuento moderado" },
  nuevo:       { pts: 0.10, l: "Cliente nuevo — captar la primera operación" },
  decreciente: { pts: 0.15, l: "A la baja — descuento para recuperar SOW" },
  competencia: { pts: 0.20, l: "0% con nosotros — oferta competitiva" },
};
// Estado de SOW de una oportunidad, normalizado a las claves de SOW_AJUSTE.
function sowEstado(deal) {
  if (!deal) return "estable";
  if (deal.superaTarget) return "target";
  if (deal.sowActualPct === 0) return "competencia";
  const t = deal.sowTendencia;
  if (t === "Creciendo") return "creciendo";
  if (t === "Decreciente") return "decreciente";
  if (t === "Nuevo" || deal.sowActualPct == null) return "nuevo";
  return "estable";
}
// Spread sugerido para un deudor dentro de una oportunidad: estándar − ajuste por SOW, truncado por el
// spread mínimo del deudor. `topado` indica que el riesgo del deudor impidió aplicar todo el descuento.
function spreadSugerido(deudor, deal) {
  const a = SOW_AJUSTE[sowEstado(deal)] || SOW_AJUSTE.estable;
  const piso = spreadMinDeudor(deudor);
  const bruto = +(SPREAD_ESTANDAR - a.pts).toFixed(2);
  return { spread: +Math.max(piso, bruto).toFixed(2), piso, bruto, ajuste: a.pts, label: a.l, topado: bruto < piso };
}

