      out.push({ id: `CAND-${deal.id}-${i}`, folio: 20000000 + (h % 8999999), tipo: "Factura electrónica (33)", deudor: deal.deudor, montoMM: +(total / n).toFixed(1), venc: diasPagoDeudor(deal.deudor), candidata: true });
