  for (const f of disp) {
    if (yaEnOp.has(f.id)) continue;
    out.push({ ...f, candidata: true, otro: true, venc: f.venc || diasPagoDeudor(f.deudor) });
  }
  // Facturas RETIRADAS de la oferta: vuelven al pool de candidatas conservando su deudor/tipo
