  macVigente: "MAC vigente", macStatus: "estado del MAC", ivaAlDia: "IVA al día", art85Vig: "artículo 85 vigente",
  uafVig: "ficha UAF vigente", contratoMarco: "contrato marco firmado", syncSII: "sincronizado con SII",
  pagaresSuf: "pagarés suficientes", pagareCubre60: "pagaré que cubre 60d post-vencimiento",
