const MSG_TIPOS = { requerimiento: { l: "Requerimiento de información para otorgamiento", c: "#5B21D6", bg: "#F1ECFF" }, general: { l: "Mensaje interno", c: "#0f766e", bg: "#f0fdfa" } };
