  const [soloMias, setSoloMias] = useState(true); // por defecto: solo lo que este usuario puede accionar
  const [form, setForm] = useState({}); // { [dealId-ruleN]: { open:"decision"|"info", dec, msg, arch, dest } }
  const setF = (k, patch) => setForm((m) => ({ ...m, [k]: { ...(m[k] || {}), ...patch } }));
  const puede = (regla, nivel) => puedeAprobarExc(usuario, regla, nivel);
