  const limpiarFiltros = () => { setFEstado("todos"); setFSow("todos"); setFDeudor("todos"); setFLinea("todos"); };
  // ALCANCE POR ROL (una sola fuente de verdad): ejecutivo → su cartera; jefe de grupo → sus
