  const execsFiltrados = useMemo(() => base.filter((e) => (fZona === "todas" || e.zona === fZona) && (fJefatura === "todas" || e.jefatura === fJefatura) && (fEjec === "todos" || e.nombre === fEjec)), [fZona, fJefatura, fEjec, soloExec, usuario]);
