  const hayFiltro = !!soloExec || !!jefeInis || fZona !== "todas" || fJefatura !== "todas" || fEjec !== "todos" || fEstado !== "todos" || fSow !== "todos";
  const filtrosDeal = { deudor: fDeudor, linea: fLinea };
