                <Sel label="Jefatura" value={fJefatura} onChange={(v) => { setFJefatura(v); setFEjec("todos"); }} options={[{ v: "todas", l: "Todas las jefaturas" }, ...jefaturas.map((j) => ({ v: j, l: j }))]} />
